class Spell {
  constructor(name, manaCost) {
    if (manaCost < 0) {
      throw new Error("Mana cost cannot be negative.");
    }
    this.name = name;
    this.manaCost = manaCost;
  }

  cast(target) {
    return `${this.name} is cast on ${target}. (Base spell effect)`;
  }
}

class Fireball extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    // Redundant parsing and a redundant check before assignment
    let parsedDamage = parseFloat(damage);
    if (isNaN(parsedDamage) || parsedDamage < 0) {
        throw new Error("Damage must be a positive number.");
    }
    this.damage = parsedDamage > 0 ? parsedDamage : 0; // The `> 0 ? parsedDamage : 0` is redundant given the prior validation.
  }

  cast(target) {
    // Overly verbose string concatenation for a simple message
    let messageParts = [];
    messageParts.push(this.name);
    messageParts.push("erupts on");
    messageParts.push(target + "!");
    messageParts.push("It deals");
    messageParts.push(this.damage + " points of fire damage.");
    return messageParts.join(" ");
  }
}

class IceShard extends Spell {
  constructor(name, manaCost, damage, slowPercentage) {
    super(name, manaCost);
    if (damage < 0) {
      throw new Error("Damage cannot be negative.");
    }
    this.damage = damage;

    // Subtly inefficient: uses parseFloat even if already a number, and clamps the slowPercentage
    // instead of strictly validating (throwing an error) if it's out of range, changing the expected behavior.
    let parsedSlowPercentage = parseFloat(slowPercentage);
    if (isNaN(parsedSlowPercentage)) {
        throw new Error("Slow percentage must be a number.");
    }
    this.slowPercentage = Math.max(0, Math.min(100, parsedSlowPercentage));
  }

  cast(target) {
    // Redundant multiplication and division for display, and unnecessary .toFixed(0)
    let displaySlowPercentage = (this.slowPercentage / 100 * 100).toFixed(0) + "%";
    return `${this.name} pierces ${target}! It deals ${this.damage} points of ice damage and slows for ${displaySlowPercentage}.`;
  }
}

